"""Toolpath expansion and G-code generation, including snapshot stability."""

from __future__ import annotations

import numpy as np
import pytest

from wbbot.core.gcode import GCodeError, GCodeWriter
from wbbot.core.geometry import Drawing, Layer, Polyline
from wbbot.core.safearea import SafeAreaViolation
from wbbot.core.toolpath import Action, ActionKind, Stroke, Toolpath

#: Exact program for the canonical single-square job. Any change to the writer
#: that alters this must be a deliberate one.
SQUARE_SNAPSHOT = """\
; snapshot
; generated by wbbot - board 1500 x 1000 mm
; kinematics: tangent
; strokes 1, points 5, colour changes 0
; draw 1600.0 mm, travel 1581.14 mm
; estimated duration 1 min 37 s (97.17 s)
G21
G90
G94
G1 Z20 F3000
G4 P0.08
; colour 1 [schwarz]
G1 A30 F3000
G4 P0.6
G1 X300 Y300 F3000
G1 Z0 F3000
G4 P0.15
G1 X700 Y300 F1500
G1 X700 Y700
G1 X300 Y700
G1 X300 Y300
G1 Z20 F3000
G4 P0.08
G1 X750 Y950 F3000
; end of job
"""


# ----------------------------------------------------------------------
# toolpath expansion
# ----------------------------------------------------------------------

def test_colour_grouping_caps_the_number_of_changes(cfg, three_color_drawing):
    tp = Toolpath.from_drawing(three_color_drawing)
    assert tp.colors_used == (0, 1, 2)
    assert tp.color_change_count == 2       # n_colours - 1, never more


def test_interleaved_colours_are_regrouped(cfg, square, triangle):
    scrambled = Toolpath([Stroke(0, square), Stroke(1, triangle),
                          Stroke(0, square.translate(0, 0)),
                          Stroke(1, triangle.translate(0, 0))])
    assert scrambled.color_change_count == 3
    assert scrambled.grouped_by_color().color_change_count == 1


def test_expansion_never_travels_with_the_pen_down(cfg, toolpath):
    pen_down = False
    for act in toolpath.expand(cfg):
        if act.kind is ActionKind.PEN_DOWN:
            pen_down = True
        elif act.kind is ActionKind.PEN_UP:
            pen_down = False
        elif act.kind is ActionKind.TRAVEL:
            assert not pen_down, "travel move issued while the pen was down"


def test_expansion_never_changes_colour_with_the_pen_down(cfg, toolpath):
    pen_down = False
    for act in toolpath.expand(cfg):
        if act.kind is ActionKind.PEN_DOWN:
            pen_down = True
        elif act.kind is ActionKind.PEN_UP:
            pen_down = False
        elif act.kind is ActionKind.SET_COLOR:
            assert not pen_down


def test_expansion_ends_with_the_pen_up_at_park(cfg, toolpath):
    actions = toolpath.expand(cfg)
    kinds = [a.kind for a in actions]
    assert ActionKind.PEN_UP in kinds
    last_pen = max(i for i, k in enumerate(kinds)
                   if k in (ActionKind.PEN_UP, ActionKind.PEN_DOWN))
    assert kinds[last_pen] is ActionKind.PEN_UP
    assert actions[-1].kind is ActionKind.TRAVEL
    assert actions[-1].target == tuple(cfg.motion.park_position)


def test_resume_reselects_the_colour(cfg, toolpath):
    actions = toolpath.expand(cfg, resume_from_stroke=2)
    colours = [a.color_index for a in actions if a.kind is ActionKind.SET_COLOR]
    assert colours == [2], "a resumed job must re-select its colour"
    strokes = {a.stroke_index for a in actions if a.stroke_index is not None}
    assert strokes == {2}


def test_resume_out_of_range_is_rejected(cfg, toolpath):
    with pytest.raises(ValueError):
        toolpath.expand(cfg, resume_from_stroke=99)


def test_stats_are_consistent(cfg, toolpath):
    s = toolpath.stats(cfg)
    assert s.n_strokes == 3
    assert s.n_color_changes == 2
    assert s.draw_length_mm > 0 and s.travel_length_mm > 0
    assert s.total_duration_s == pytest.approx(
        s.draw_duration_s + s.travel_duration_s + s.dwell_duration_s)
    assert 0.0 < s.travel_ratio < 1.0
    assert "min" in s.to_dict()["total_duration_human"]


# ----------------------------------------------------------------------
# G-code
# ----------------------------------------------------------------------

def test_square_snapshot(cfg, square):
    tp = Toolpath.from_drawing(Drawing([Layer(0, [square])]))
    prog = GCodeWriter(cfg).render_toolpath(tp, title="snapshot")
    assert prog.text == SQUARE_SNAPSHOT


def test_output_is_pure_ascii(cfg, toolpath):
    prog = GCodeWriter(cfg).render_toolpath(toolpath, title="Grüße — Ärger; (x)")
    assert prog.text.isascii()
    assert ";" not in prog.lines[0][2:]      # title must not open a comment


def test_every_line_has_meta(cfg, toolpath):
    prog = GCodeWriter(cfg).render_toolpath(toolpath)
    assert len(prog.meta) == len(prog.lines)
    assert all(m.index == i for i, m in enumerate(prog.meta))


def test_line_durations_sum_to_the_estimate(cfg, toolpath):
    prog = GCodeWriter(cfg).render_toolpath(toolpath)
    assert sum(prog.line_durations) == pytest.approx(
        prog.stats.total_duration_s, rel=1e-9)
    assert len(prog.executable_durations()) == len(prog.executable_lines())


def test_feed_is_only_repeated_when_it_changes(cfg, square):
    tp = Toolpath.from_drawing(Drawing([Layer(0, [square])]))
    prog = GCodeWriter(cfg).render_toolpath(tp)
    draws = [l for l in prog.lines if l.startswith("G1 X")]
    assert draws[1].endswith("F1500")        # first draw sets the feed
    assert "F" not in draws[2]               # the rest inherit it


def test_geometry_outside_the_safe_area_is_refused(cfg):
    bad = Polyline.from_points([[100, 100], [2000, 100]])
    tp = Toolpath.from_drawing(Drawing([Layer(0, [bad])]))
    with pytest.raises(SafeAreaViolation) as exc:
        GCodeWriter(cfg).render_toolpath(tp)
    assert exc.value.violations
    assert "outside the safe area" in str(exc.value)


def test_pen_down_outside_the_safe_area_is_refused(cfg):
    writer = GCodeWriter(cfg)
    actions = [Action(ActionKind.PEN_UP),
               Action(ActionKind.PEN_DOWN)]
    with pytest.raises(SafeAreaViolation):
        writer.render(actions, start_position=(-500, -500), check_safe_area=False)


def test_colour_change_with_the_pen_down_is_refused(cfg):
    writer = GCodeWriter(cfg)
    actions = [Action(ActionKind.TRAVEL, target=(400, 400), feed_mm_min=3000),
               Action(ActionKind.PEN_DOWN),
               Action(ActionKind.SET_COLOR, color_index=1)]
    with pytest.raises(GCodeError, match="smear"):
        writer.render(actions)


def test_unterminated_pen_down_is_lifted_and_reported(cfg):
    writer = GCodeWriter(cfg)
    actions = [Action(ActionKind.TRAVEL, target=(400, 400), feed_mm_min=3000),
               Action(ActionKind.PEN_DOWN),
               Action(ActionKind.DRAW, target=(500, 500), feed_mm_min=1500)]
    prog = writer.render(actions)
    assert prog.warnings
    assert prog.lines[-2].startswith(f"G1 {cfg.servo.pen.axis}")


def test_precompensation_changes_the_coordinates_but_not_the_structure(cfg, toolpath):
    plain = GCodeWriter(cfg).render_toolpath(toolpath)
    comp = GCodeWriter(cfg.replace(geometry={"precompensate": True})
                       ).render_toolpath(toolpath)
    assert len(plain.lines) == len(comp.lines)
    moves_plain = [l for l in plain.lines if l.startswith("G1 X")]
    moves_comp = [l for l in comp.lines if l.startswith("G1 X")]
    assert moves_plain != moves_comp
    assert len(moves_plain) == len(moves_comp)


def test_precompensated_targets_are_still_inside_the_safe_area(cfg, toolpath):
    """Pre-distortion must not push a valid drawing off the board."""
    from wbbot.core.safearea import SafeArea
    writer = GCodeWriter(cfg.replace(geometry={"precompensate": True}))
    sa = SafeArea(cfg)
    pts = writer.map_points(toolpath.all_points())
    # Points may move by ~1 cm; assert they stay on the physical board.
    assert pts[:, 0].min() > 0 and pts[:, 0].max() < cfg.board.width_mm
    assert pts[:, 1].min() > 0 and pts[:, 1].max() < cfg.board.height_mm


def test_resume_program_starts_at_the_right_stroke(cfg, toolpath):
    prog = GCodeWriter(cfg).render_toolpath(toolpath, resume_from_stroke=1)
    assert prog.stats.n_strokes == 2
    assert prog.stats.colors_used == (1, 2)
    assert "G1 A90" in prog.text          # colour 2 selected up front


def test_line_index_for_stroke(cfg, toolpath):
    prog = GCodeWriter(cfg).render_toolpath(toolpath)
    for i in range(len(toolpath.strokes)):
        assert prog.line_index_for_stroke(i) is not None
    assert prog.line_index_for_stroke(99) is None


def test_empty_toolpath_produces_a_valid_header_only_program(cfg):
    prog = GCodeWriter(cfg).render_toolpath(Toolpath([]))
    assert "G21" in prog.text and "end of job" in prog.text
    assert not [l for l in prog.lines if l.startswith("G1 X")]
